CREATE DATABASE IF NOT EXISTS crownfield_eye_hospital;
USE crownfield_eye_hospital;
CREATE TABLE patient(patient_id VARCHAR(10) PRIMARY KEY,given_name VARCHAR(60) NOT NULL,family_name VARCHAR(60) NOT NULL,postcode VARCHAR(10) NOT NULL,date_of_birth DATE NOT NULL);
CREATE TABLE specialty(specialty_id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,specialty_name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE clinician(clinician_id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,given_name VARCHAR(60) NOT NULL,family_name VARCHAR(60) NOT NULL,specialty_id SMALLINT UNSIGNED NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(specialty_id) REFERENCES specialty(specialty_id));
CREATE TABLE clinic(clinic_id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,clinic_name VARCHAR(80) NOT NULL UNIQUE,address_line VARCHAR(150) NOT NULL);
CREATE TABLE appointment(appointment_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id VARCHAR(10) NOT NULL,clinician_id SMALLINT UNSIGNED NOT NULL,clinic_id SMALLINT UNSIGNED NOT NULL,appointment_date DATE NOT NULL,appointment_time TIME NOT NULL,status ENUM('Scheduled','Completed','Cancelled','Did not attend') NOT NULL DEFAULT 'Scheduled',notes VARCHAR(500),UNIQUE(clinician_id,appointment_date,appointment_time),FOREIGN KEY(patient_id) REFERENCES patient(patient_id),FOREIGN KEY(clinician_id) REFERENCES clinician(clinician_id),FOREIGN KEY(clinic_id) REFERENCES clinic(clinic_id),CHECK(appointment_date >= '2000-01-01'));
CREATE TABLE diagnosis(diagnosis_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,appointment_id INT UNSIGNED NOT NULL,diagnosis_name VARCHAR(120) NOT NULL,diagnosis_code VARCHAR(20),diagnosed_on DATE NOT NULL,FOREIGN KEY(appointment_id) REFERENCES appointment(appointment_id) ON DELETE CASCADE);
CREATE TABLE medicine(medicine_id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,medicine_name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE prescription(prescription_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,appointment_id INT UNSIGNED NOT NULL,prescribed_on DATE NOT NULL,FOREIGN KEY(appointment_id) REFERENCES appointment(appointment_id) ON DELETE CASCADE);
CREATE TABLE prescription_item(prescription_id INT UNSIGNED NOT NULL,medicine_id SMALLINT UNSIGNED NOT NULL,dose VARCHAR(80) NOT NULL,route VARCHAR(40) NOT NULL,frequency VARCHAR(80) NOT NULL,duration_days SMALLINT UNSIGNED NOT NULL,PRIMARY KEY(prescription_id,medicine_id),FOREIGN KEY(prescription_id) REFERENCES prescription(prescription_id) ON DELETE CASCADE,FOREIGN KEY(medicine_id) REFERENCES medicine(medicine_id),CHECK(duration_days > 0));
CREATE TABLE follow_up_plan(follow_up_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,appointment_id INT UNSIGNED NOT NULL UNIQUE,due_date DATE NOT NULL,priority ENUM('Routine','High','Urgent') NOT NULL DEFAULT 'Routine',status ENUM('Planned','Booked','Completed','Cancelled') NOT NULL DEFAULT 'Planned',plan_notes VARCHAR(300),FOREIGN KEY(appointment_id) REFERENCES appointment(appointment_id) ON DELETE CASCADE,CHECK(due_date >= '2000-01-01'));
CREATE TABLE appointment_audit(audit_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,appointment_id INT UNSIGNED NOT NULL,old_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(appointment_id) REFERENCES appointment(appointment_id));
ALTER TABLE appointment_audit ADD COLUMN changed_by VARCHAR(100) NOT NULL DEFAULT 'system';
